mapper.select:
select mn.*, su.u_Name as spPAreamanagerUname, (select GROUP_CONCAT(DISTINCT sc.mf_Source ORDER BY sc.mf_Source SEPARATOR ',') from sporadic_contract sc where sc.sp_id = mn.id) as mfSource, (select GROUP_CONCAT(DISTINCT sc.mf_Code ORDER BY sc.mf_Code SEPARATOR ',') from sporadic_contract sc where sc.sp_id = mn.id) as mfCode from sporadic_payments mn left join sys_user su on su.u_Id = mn.sp_p_areamanager_uid where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.create_Time desc

select
mn.*,
su.u_Name as spPAreamanagerUname,
(
select LISTAGG(t.mf_source, ',') WITHIN GROUP (ORDER BY t.mf_source)
from (
select distinct sc.mf_source
from sporadic_contract sc
where sc.sp_id = mn.id
) t
) as mfSource,
(
select LISTAGG(t.mf_code, ',') WITHIN GROUP (ORDER BY t.mf_code)
from (
select distinct sc.mf_code
from sporadic_contract sc
where sc.sp_id = mn.id
) t
) as mfCode
from sporadic_payments mn
left join sys_user su on su.u_Id = mn.sp_p_areamanager_uid
where 1=1


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.create_Time desc

select stp.tp_user from Sys_Task_Processin stp
left join SYS_FlowActivity act on act.actid = stp.tp_actid
where
act.actcode=#{actCode}
and
    stp.tp_entityid in

    #{id}

limit 1;
